head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};

// 사전 조건 : 두 그리드의 dataType="float" Body Column (인덱스 0) 에 maxLength 를 설정한다.
//  - setMaxLength 는 JS 로만 호출 가능하므로 onpageload 에서 처리한다. (출력 없음)
scwin.onpageload = function () {
    grd_a.setMaxLength(0, "*.");
    grd_b.setMaxLength(0, ".");
};

// 편집 종료(포커스 아웃) 시 저장값과 정수부/소수부 자릿수를 1 줄 출력
scwin.printEdit = function (strGrid, value) {
    var strValue = String(value);
    var arrPart = strValue.split(".");
    var intLen = arrPart[0].length;
    var floatLen = (arrPart.length > 1) ? arrPart[1].length : 0;

    scwin.setReturnValue(strGrid + " 저장값 : '" + strValue + "' (정수부 " + intLen + "자리 / 소수부 " + floatLen + "자리)");
};

scwin.grd_a_onafteredit = function (rowIndex, columnIndex, value) {
    scwin.printEdit("[A] setMaxLength(0, \"*.\")", value);
};

scwin.grd_b_onafteredit = function (rowIndex, columnIndex, value) {
    scwin.printEdit("[B] setMaxLength(0, \".\") ", value);
};
